public string ReverseWords(string s)
{
    var words = new List<string>();
    int i = 0;
    while (i < s.Length)
    {
        while (i < s.Length && s[i] == ' ') i++;
        if (i >= s.Length) break;
        int j = i;
        while (j < s.Length && s[j] != ' ') j++;
        words.Add(s.Substring(i, j - i));
        i = j;
    }
    words.Reverse();
    return string.Join(" ", words);
}
